import { escape as e, number, money, pot, count, category, soon, ended, timeLeft, date, route, link } from './format.js';

export const external = (url, label, cls = '') => `<a class="${cls}" href="${link(url)}" target="_blank" rel="noopener noreferrer">${e(label)} <span aria-hidden="true">↗</span></a>`;
export const timer = value => `<time datetime="${e(value || '')}" data-deadline="${e(value || '')}" class="time ${soon(value) ? 'urgent' : ''} ${ended(value) ? 'ended' : ''}" title="${e(date(value, true))} UTC">${e(timeLeft(value))}</time>`;
const heading = titles => `<thead><tr>${titles.map(t => `<th scope="col">${e(t)}</th>`).join('')}</tr></thead>`;
export const table = (titles, rows, cls = '') => `<div class="table-scroll ${cls}" tabindex="0" aria-label="${cls === 'standings' ? 'Leaderboard' : 'Data table'}, scroll horizontally"><table>${heading(titles)}<tbody>${rows || `<tr><td colspan="${titles.length}" class="empty-cell">Nothing here yet. Check back soon.</td></tr>`}</tbody></table></div>`;
export const tag = value => `<span class="tag">${e(value)}</span>`;
export const crumb = (href, label, current) => `<div class="crumb"><a href="${href}">← ${e(label)}</a>${current ? `<span>/</span><span>${e(current)}</span>` : ''}</div>`;
const option = (value, label, selected) => `<option value="${e(value)}" ${value === selected ? 'selected' : ''}>${e(label)}</option>`;
export const filters = { q: '', category: 'all', state: 'all', sort: 'deadline' };

export function boardItems(items, f) {
  const comparators = { deadline: (a,b) => Date.parse(a.deadline) - Date.parse(b.deadline), pot: (a,b) => pot(b)-pot(a), entries: (a,b) => count(b)-count(a), title: (a,b) => String(a.title).localeCompare(String(b.title)) };
  const query = f.q.trim().toLowerCase();
  const visible = items.filter(c => (!query || `${c.title} ${c.summary || ''} ${category(c)}`.toLowerCase().includes(query)) && (f.category === 'all' || category(c) === f.category) && (f.state === 'all' || (f.state === 'soon' ? soon(c.deadline) : ended(c.deadline)))).sort(comparators[f.sort]);
  return { count: visible.length, html: visible.map(c => `<li class="bounty-row"><div class="bounty-info"><span class="category-icon" aria-hidden="true">${e(category(c)[0])}</span><div>${tag(category(c))}<a class="bounty-title" href="${route(c.slug)}">${e(c.title)}</a><p>${e(c.summary || c.description || 'Explore the brief and start building.')}</p></div></div><div class="row-pot"><strong>${money(pot(c))}</strong><small>${Number(c.entryFeeUsd) ? money(c.entryFeeUsd) + ' entry fee' : 'Free to enter'}</small></div><div>${timer(c.deadline)}<small>${date(c.deadline)}</small></div><div class="row-count"><b>${number(count(c))}</b><small>entries</small></div><a class="row-arrow" href="${route(c.slug)}" aria-label="View ${e(c.title)}">↗</a></li>`).join('') || '<li class="empty"><h2>No bounties found</h2><p>Try a different search or clear your filters.</p><button data-reset>Clear filters</button></li>' };
}
export function boardPage(items, f) {
  const live = items.filter(c => !ended(c.deadline));
  const categories = [...new Set(items.map(category))].sort();
  const rows = boardItems(items, f);
  return `<section class="board-hero"><div><p class="eyebrow">A playground for ambitious builders</p><h1>Good ideas.<br><span>Real rewards.</span></h1><p class="intro">Pick a challenge. Make your mark. Get rewarded.</p></div><aside class="pot-card"><span class="card-label"><i></i> Total live pots</span><strong>${money(live.reduce((n,c) => n + pot(c), 0))}</strong><div><span><b>${live.length}</b> live bounties</span><span><b>${live.filter(c => soon(c.deadline)).length}</b> closing soon</span></div></aside></section><section class="board-section" aria-label="Bounty board"><div class="section-heading"><h2>Find your next build<span class="dot">.</span></h2><span class="muted">Open challenges, endless possibilities</span></div><form class="filters" role="search"><label class="search"><span aria-hidden="true">⌕</span><input name="q" type="search" placeholder="Search bounties…" value="${e(f.q)}" aria-label="Search bounties"></label><label><span class="sr-only">Category</span><select name="category">${option('all','All categories',f.category)}${categories.map(c => option(c,c,f.category)).join('')}</select></label><label><span class="sr-only">State</span><select name="state">${[['all','All states'],['soon','Closing soon · <24h'],['ended','Ended']].map(([v,l]) => option(v,l,f.state)).join('')}</select></label><label><span class="sort-label">Sort by</span><select name="sort">${[['deadline','Deadline'],['pot','Live pot'],['entries','Entries'],['title','Title']].map(([v,l]) => option(v,l,f.sort)).join('')}</select></label></form><div class="board-labels"><span><b id="match-count">${rows.count}</b> bounties</span><span>Live pot</span><span>Closes</span><span>Entries</span><span></span></div><ul id="bounty-list">${rows.html}</ul><div id="board-more"></div></section>`;
}

export function loading() { return '<section class="loading"><p class="eyebrow">Finding the good stuff</p><h1>Loading make.fun<span class="dot">.</span></h1><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></section>'; }
export function failure(message) { return `<section class="empty error"><span class="error-symbol" aria-hidden="true">↯</span><p class="eyebrow">A little interruption</p><h1>Couldn’t load this page.</h1><p>${e(message)}</p><button id="retry">Try again</button><a href="#/">Back to bounties →</a></section>`; }
```

