  const payouts = rewards.map(r => `<tr><td class="place">#${e(r.place)}</td><td>${money(r.baseUsd)}</td><td>${money(r.feeShareUsd)}</td><td class="green">${money(r.amountUsd)}</td></tr>`).join('');
